="creature-gorilla",["journalFields"]={},["kind"]="creature",["period"]="classic",["related"]={},["sourceIdentifiers"]={{["namespace"]="reference-url",["value"]="https://warcraft.wiki.gg/wiki/Gorilla"}},["sourceURL"]="https://warcraft.wiki.gg/wiki/Gorilla",["sourceVersion"]="world-facts-2026-10-26-r5",["title"]="Gorillas"},{["aliases"]={"Hyenas","Hyena"},["category"]="creatures",["editorialStatus"]="ORIGINAL_AUTHOR_REVIEW; FIELD_SOURCE_QUALIFIED; NOT_EXHAUSTIVE",["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="hyena",["receiptSHA256"]="1ca9bb5988b332f965ada6190de0fc4ba8cdfcd81c105393e66b5706cbeccc01"},["location"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="hyena",["receiptSHA256"]="1ca9bb5988b332f965ada6190de0fc4ba8cdfcd81c105393e66b5706cbeccc01"},["relationships"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="hyena",["receiptSHA256"]="1ca9bb5988b332f965ada6190de0fc4ba8cdfcd81c105393e66b5706cbeccc01"}},["fields"]={["appearance"]="Hyenas were large carnivores with formidable strength in their jaws.",["location"]="They were familiar hunters and scavengers in Kalimdor’s barren country, particularly dangerous when gathered in packs.",["relationships"]="Centaur hunters in the Barrens and Desolace kept hyenas as companions."},["gate"]="HISTORICAL",["id"]="creature-hyena",["journalFields"]={"appearance"},["kind"]="creature",["period"]="classic",["related"]={},["sourceIdentifiers"]={{["namespace"]="reference-url",["value"]="https://warcraft.wiki.gg/wiki/Dire_hyena"}},["sourceURL"]="https://warcraft.wiki.gg/wiki/Dire_hyena",["sourceVersion"]="world-facts-2026-10-26-r5",["title"]="Hyenas"},{["aliases"]={"Crabs","Crab","Crawlers","Crawler"},["category"]="creatures",["editorialStatus"]="ORIGINAL_AUTHOR_REVIEW; FIELD_SOURCE_QUALIFIED; NOT_EXHAUSTIVE",["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="crab",["receiptSHA256"]="906f2ce32477faaca05a0ad88062428da451b37b761fa671c9aa89fb62fa1690"},["