don"},["category"]="creatures",["editorialStatus"]="ORIGINAL_AUTHOR_REVIEW; FIELD_SOURCE_QUALIFIED; NOT_EXHAUSTIVE",["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="diemetradon",["receiptSHA256"]="f0bebe891026db42d4ece10111459b1b0e1ef06511295bb490ec2e78c0dcaf46"},["context"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="diemetradon",["receiptSHA256"]="f0bebe891026db42d4ece10111459b1b0e1ef06511295bb490ec2e78c0dcaf46"},["location"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="diemetradon",["receiptSHA256"]="f0bebe891026db42d4ece10111459b1b0e1ef06511295bb490ec2e78c0dcaf46"}},["fields"]={["appearance"]="Two large skin-covered sails rose along a diemetradon's back on extended vertebral spines.",["context"]="The Slag Pit held red, fire-breathing relatives called incendosaurs among its lava pools.",["location"]="Diemetradons inhabited Un'Goro, while subterranean kinds lived within Maraudon."},["gate"]="HISTORICAL",["id"]="creature-diemetradon",["journalFields"]={"appearance"},["kind"]="creature",["period"]="classic",["related"]={},["sourceIdentifiers"]={{["namespace"]="reference-url",["value"]="https://warcraft.wiki.gg/wiki/Diemetradon"}},["sourceURL"]="https://warcraft.wiki.gg/wiki/Diemetradon",["sourceVersion"]="world-facts-2026-10-26-r5",["title"]="Diemetradons"},{["aliases"]={"Oozes","Ooze","Slimes","Slime","Oozelings","Oozeling"},["category"]="creatures",["editorialStatus"]="ORIGINAL_AUTHOR_REVIEW; FIELD_SOURCE_QUALIFIED; NOT_EXHAUSTIVE",["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="ooze",["receiptSHA256"]="ba363d0e5473770ca0e14f27be76c8375360dd1dfdd76c73f876c04e0f4142a4"},["context"]={["method"]="PUBLIC_INDEXED_EXCERPT",["receiptID"]="ooze",["receiptSHA256"]="ba363d0e5473770ca0e14f27be76c8375360dd1dfdd76c73f876c04e0f4142a4"}},["fields"]={["appearance"]="Oozes were slime creatures, many bearing bones within their bodies or a skull serving as a head.",["context"]="Their motivation