local byID,titles={},{}
for _,e in ipairs(D.entries) do byID[e.id]=e;titles[e.title]=e end
for _,row in ipairs(additions) do
 assert(not byID[row.id] and not titles[row.title],"Duplicate world codex identity")
 D.entries[#D.entries+1]=row;byID[row.id]=row;titles[row.title]=row
end
for _,row in ipairs(updates) do
 local e=assert(byID[row.id],"Missing canonical battlefield")
 assert(e.kind==row.expectedKind and e.category==row.category,"Wrong battlefield target")
 e.fieldSources=e.fieldSources or {};e.fieldEvidence=e.fieldEvidence or {}
 for field,text in pairs(row.fields) do
  e.fields[field]=text;e.fieldSources[field]=row.fieldSources[field];e.fieldEvidence[field]=row.fieldEvidence[field]
 end
 e.referenceRules=row.referenceRules;e.sourceVersion=row.sourceVersion
end
-- Major historical actors can illuminate a plot even when they are not its
-- giver/target. Ordinary incidental names do not force a detached biography.
for _,id in ipairs({"illidan","arthas","azshara","thrall","jaina","tyrande","malfurion","sylvanas"}) do
 local e=byID[id];if e then e.journalMentionRelevant=true end
end
